package offline;

import de.rub.nds.tlsattacker.core.quic.util.VariableLengthIntegerEncoding;
import java.io.ByteArrayOutputStream;

/** Canonical frame model: preserves type, order, optional flags and opaque payload bytes. */
final class Frame {
    static final byte[] NO_BYTES = new byte[0];
    static final long[] NO_LONGS = new long[0];

    /** Frame type value. */
    long type;
    /** Body varints, meaning depends on the type. */
    long v1;
    long v2;
    long v3;
    /** ECN counters of an ACK_ECN frame. */
    long e0;
    long e1;
    long e2;
    /** ACK (gap, range) pairs in wire order. */
    long[] pairs = NO_LONGS;
    /** Half-open acknowledged intervals derived from an ACK frame. */
    long[] intervals = NO_LONGS;
    /** Opaque payload bytes. */
    byte[] data = NO_BYTES;
    /** NEW_CONNECTION_ID bytes. */
    byte[] cid = NO_BYTES;
    byte[] token = NO_BYTES;
    long cidLen;
    /** STREAM flag bits. */
    boolean hasOffset;
    boolean hasLength;
    boolean fin;
    /** Payload offset just after this frame. */
    int end;

    static Frame of(long type) {
        Frame f = new Frame();
        f.type = type;
        return f;
    }

    /** Minimal-varint re-encoding; lengthless frames stay lengthless. */
    static byte[] encode(Frame f) {
        Out o = new Out();
        int t = (int) f.type;
        switch (t) {
            case 0x00:
                o.one(0x00);
                return o.out();
            case 0x01:
                o.one(0x01);
                return o.out();
            case 0x02:
            case 0x03:
                o.v(t);
                o.v(f.v1);
                o.v(f.v2);
                o.v(f.v3);
                for (int i = 0; i < f.pairs.length; i++) {
                    o.v(f.pairs[i]);
                }
                if (t == 0x03) {
                    o.v(f.e0);
                    o.v(f.e1);
                    o.v(f.e2);
                }
                return o.out();
            case 0x04:
                o.v(0x04);
                o.v(f.v1);
                o.v(f.v2);
                o.v(f.v3);
                return o.out();
            case 0x05:
                o.v(0x05);
                o.v(f.v1);
                o.v(f.v2);
                return o.out();
            case 0x06:
                o.v(0x06);
                o.v(f.v1);
                o.v(f.v2);
                o.raw(f.data);
                return o.out();
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f:
                o.v(t);
                o.v(f.v1);
                if (f.hasOffset) {
                    o.v(f.v2);
                }
                if (f.hasLength) {
                    o.v(f.v3);
                }
                o.raw(f.data);
                return o.out();
            case 0x10:
                o.v(0x10);
                o.v(f.v1);
                return o.out();
            case 0x11:
                o.v(0x11);
                o.v(f.v1);
                o.v(f.v2);
                return o.out();
            case 0x12:
            case 0x13:
                o.v(t);
                o.v(f.v1);
                return o.out();
            case 0x14:
                o.v(0x14);
                o.v(f.v1);
                return o.out();
            case 0x15:
                o.v(0x15);
                o.v(f.v1);
                o.v(f.v2);
                return o.out();
            case 0x16:
            case 0x17:
                o.v(t);
                o.v(f.v1);
                return o.out();
            case 0x18:
                o.v(0x18);
                o.v(f.v1);
                o.v(f.v2);
                o.one((int) f.cidLen);
                o.raw(f.cid);
                o.raw(f.token);
                return o.out();
            case 0x19:
                o.v(0x19);
                o.v(f.v1);
                return o.out();
            case 0x1a:
            case 0x1b:
                o.v(t);
                o.raw(f.data);
                return o.out();
            case 0x1c:
                o.v(0x1c);
                o.v(f.v1);
                o.v(f.v2);
                o.v(f.v3);
                o.raw(f.data);
                return o.out();
            case 0x1d:
                o.v(0x1d);
                o.v(f.v1);
                o.v(f.v2);
                o.raw(f.data);
                return o.out();
            case 0x30:
                o.one(0x30);
                o.raw(f.data);
                return o.out();
            case 0x31:
                o.v(0x31);
                o.v(f.v1);
                o.raw(f.data);
                return o.out();
            default:
                throw new IllegalStateException("unsupported frame type " + f.type);
        }
    }

    private static final class Out {
        private final ByteArrayOutputStream buffer = new ByteArrayOutputStream();

        void v(long value) {
            byte[] encoded = VariableLengthIntegerEncoding.encodeVariableLengthInteger(value);
            buffer.write(encoded, 0, encoded.length);
        }

        void one(int value) {
            buffer.write(value);
        }

        void raw(byte[] bytes) {
            buffer.write(bytes, 0, bytes.length);
        }

        byte[] out() {
            return buffer.toByteArray();
        }
    }
}
EOF
